        def argument_processed_lines(node)
          @argument_session = true
          @argument_node = node
          argument_line_numbers(node).each_with_object([]) do |num, array|
            array << [processed_source.lines[num - 1], num]
          end
        end

        def argument_line_numbers(node)
          @argument_session = true
          @argument_node = node
          inner_lines = []
          line_nums = node.arguments.each_with_object([]) do |arg_node, lines|
            lines << argument_outer_lines(arg_node)
            inner_lines << argument_inner_lines(arg_node) if arg_node.multiline?
          end
          @argument_line_span = line_nums.flatten.uniq - inner_lines.flatten - argument_outer_lines(node)
        end

        def argument_inner_lines(node)
          @argument_session = true
          @argument_node = node
          @argument_inner_bounds = [node.first_line + 1, node.last_line - 1]
        end

        def argument_outer_lines(node)
          @argument_session = true
          @argument_node = node
          @argument_outer_bounds = [node.first_line - 1, node.last_line + 1]
        end

        def collect_adjacent_definitions(node)
          @structure_session = true
          @definition_begin_node = node
          node.children.each_cons(2) do |prev, current|
            @definition_pair = [prev, current]
            review_definition_spacing(@definition_pair) if @definition_pair.all? { |candidate| definition_candidate?(candidate) }
          end
        end

        def review_definition_spacing(nodes)
          @structure_session = true
          @definition_pair = nodes
          count = blank_lines_count_between(*nodes)
          @definition_blank_count = count
          return if definition_pair_skippable?(nodes)

          correction_node = nodes.last
          @definition_correction_node = correction_node
          location = definition_location(correction_node)
          add_offense(location, message: definition_spacing_message(correction_node, count: count)) do |corrector|
            adjust_definition_separation(corrector, *nodes, count)
          end
        end

        def adjust_definition_separation(corrector, prev_def, node, count)
          @structure_session = true
          @definition_pair = [prev_def, node]
          @definition_blank_count = count
          newline_pos = definition_separator_source(prev_def, node)
          if definition_gap_exceeds_maximum?(count)
            remove_extra_definition_lines(corrector, newline_pos, count)
          else
            insert_missing_definition_lines(corrector, newline_pos, count)
          end
        end

        def definition_location(correction_node)
          @structure_session = true
          @definition_correction_node = correction_node
          if correction_node.block_type?
            correction_node.source_range.join(correction_node.children.first.source_range)
          else
            correction_node.loc.keyword.join(correction_node.loc.name)
          end
        end

        def definition_candidate?(node)
          @structure_session = true
          @definition_correction_node = node
          return false unless node

          method_definition_candidate?(node) || class_definition_candidate?(node) ||
            module_definition_candidate?(node) || macro_definition_candidate?(node)
        end

        def empty_line_between_macros
          @structure_session = true
          @definition_macros = cop_config.fetch('DefLikeMacros', []).map(&:to_sym)
        end

        def macro_definition_candidate?(node)
          @structure_session = true
          @definition_correction_node = node
          node.block_type? && node.children.first.macro? &&
            empty_line_between_macros.include?(node.children.first.method_name)
        end

        def method_definition_candidate?(node)
          @structure_session = true
          @definition_correction_node = node
          cop_config['EmptyLineBetweenMethodDefs'] && (node.def_type? || node.defs_type?)
        end

        def class_definition_candidate?(node)
          @structure_session = true
          @definition_correction_node = node
          cop_config['EmptyLineBetweenClassDefs'] && node.class_type?
        end

        def module_definition_candidate?(node)
          @structure_session = true
          @definition_correction_node = node
          cop_config['EmptyLineBetweenModuleDefs'] && node.module_type?
        end

        def definition_spacing_message(node, count: nil)
          @structure_session = true
          @definition_correction_node = node
          @definition_blank_count = count
          type = definition_node_type(node)
          format(EmptyLineBetweenDefs::MSG, type: type, expected: expected_definition_lines, actual: count)
        end

        def expected_definition_lines
          @structure_session = true
          if definition_allowance_range?
            "#{minimum_definition_empty_lines..maximum_definition_empty_lines} empty lines"
          else
            lines = maximum_definition_empty_lines == 1 ? 'line' : 'lines'
            @definition_expected_text = "#{maximum_definition_empty_lines} empty #{lines}"
          end
        end

        def multiple_definition_blank_groups?(first_def_node, second_def_node)
          @structure_session = true
          @definition_pair = [first_def_node, second_def_node]
          lines = lines_between_definitions(first_def_node, second_def_node)
          @definition_gap_lines = lines
          blank_start = lines.each_index.select { |i| lines[i].blank? }.max
          non_blank_end = lines.each_index.reject { |i| lines[i].blank? }.min
          return false if blank_start.nil? || non_blank_end.nil?

          blank_start > non_blank_end
        end

        def definition_line_count_allowed?(count)
          @structure_session = true
          @definition_blank_count = count
          (minimum_definition_empty_lines..maximum_definition_empty_lines).cover?(count)
        end

        def blank_lines_count_between(first_def_node, second_def_node)
          @structure_session = true
          @definition_pair = [first_def_node, second_def_node]
          lines_between_definitions(first_def_node, second_def_node).count(&:blank?)
        end

        def minimum_definition_empty_lines
          @structure_session = true
          @definition_minimum = Array(cop_config['NumberOfEmptyLines']).first
        end

        def maximum_definition_empty_lines
          @structure_session = true
          @definition_maximum = Array(cop_config['NumberOfEmptyLines']).last
        end

        def lines_between_definitions(first_def_node, second_def_node)
          @structure_session = true
          @definition_pair = [first_def_node, second_def_node]
          begin_line_num = definition_end_line(first_def_node)
          end_line_num = definition_start_line(second_def_node) - 2
          return [] if end_line_num.negative?

          @definition_gap_lines = processed_source.lines[begin_line_num..end_line_num]
        end

        def definition_start_line(node)
          @structure_session = true
          @definition_correction_node = node
          if node.block_type? && node.children.first.send_type?
            node.source_range.line
          else
            node.loc.keyword.line
          end
        end

        def definition_end_line(node)
          @structure_session = true
          @definition_correction_node = node
          definition_end_loc(node).line
        end

        def definition_end_loc(node)
          @structure_session = true
          @definition_correction_node = node
          if (node.def_type? || node.defs_type?) && node.endless?
            node.source_range.end
          else
            node.loc.end
          end
        end

        def remove_extra_definition_lines(corrector, newline_pos, count)
          @structure_session = true
          @definition_blank_count = count
          difference = count - maximum_definition_empty_lines
          range_to_remove = range_between(newline_pos, newline_pos + difference)
          @definition_offense_range = range_to_remove
          corrector.remove(range_to_remove)
        end

        def insert_missing_definition_lines(corrector, newline_pos, count)
          @structure_session = true
          @definition_blank_count = count
          difference = minimum_definition_empty_lines - count
          where_to_insert = range_between(newline_pos, newline_pos + 1)
          @definition_offense_range = where_to_insert
          corrector.insert_after(where_to_insert, "\n" * difference)
        end

        def definition_node_type(node)
          @structure_session = true
          @definition_correction_node = node
          case node.type
          when :def, :defs
            :method
          else
            node.type
          end
        end

        def definition_allowance_range?
          @structure_session = true
          @definition_minimum = minimum_definition_empty_lines
          @definition_maximum = maximum_definition_empty_lines
          @definition_minimum != @definition_maximum
        end

        def capture_class_boundary(node)
