        def inspect_access_modifier(node)
          @structure_session = true
          @access_context_node = node
          return if access_modifier_skippable?(node)

          message = access_modifier_message(node)
          @access_message = message
          previous_empty, _next_empty = access_surrounding_line_states(node)
          add_offense(node, message: message) do |corrector|
            line = range_by_whole_lines(node.source_range)
            @access_line_range = line
            corrector.insert_before(line, "\n") unless previous_empty
            access_correct_next_line_if_denied_style(corrector, node, line)
          end
        end

        def access_expected_empty_lines?(node)
          @structure_session = true
          @access_context_node = node
          case style
          when :around
            return true if access_empty_lines_around?(node)
          when :only_before
            return true if access_allowed_only_before_style?(node)
          end

          false
        end

        def access_allowed_only_before_style?(node)
          @structure_session = true
          @access_context_node = node
          if node.special_modifier?
            return true if processed_source[node.last_line] == 'end'
            return false if access_next_line_empty?(node.last_line)
          end

          access_previous_line_empty?(node.first_line)
        end

        def access_correct_next_line_if_denied_style(corrector, node, line)
          @structure_session = true
          @access_context_node = node
          @access_line_range = line
          case style
          when :around
            corrector.insert_after(line, "\n") unless access_next_line_empty?(node.last_line)
          when :only_before
            if access_next_line_empty?(node.last_line)
              range = access_next_empty_line_range(node)
              @access_line_range = range
              corrector.remove(range)
            end
          end
        end

        def access_previous_line_ignoring_comments(send_line)
          @structure_session = true
          @access_send_line = send_line
          processed_source[0..send_line - 2].reverse.find { |line| !comment_line?(line) }
        end

        def access_previous_line_empty?(send_line)
          @structure_session = true
          @access_send_line = send_line
          previous_line = access_previous_line_ignoring_comments(send_line)
          return true unless previous_line

          access_block_start?(send_line) || access_class_def?(send_line) || previous_line.blank?
        end

        def access_next_line_empty?(last_send_line)
          @structure_session = true
          @access_send_line = last_send_line
          next_line = processed_source[last_send_line]
          access_body_end?(last_send_line) || next_line.blank?
        end

        def access_empty_lines_around?(node)
          @structure_session = true
          @access_context_node = node
          access_previous_line_empty?(node.first_line) && access_next_line_empty?(node.last_line)
        end

        def access_class_def?(line)
          @structure_session = true
          @access_send_line = line
          return false unless @class_or_module_def_first_line

          line == @class_or_module_def_first_line + 1
        end

        def access_block_start?(line)
          @structure_session = true
          @access_send_line = line
          return false unless @block_line

          line == @block_line + 1
        end

        def access_body_end?(line)
          @structure_session = true
          @access_send_line = line
          return false unless @class_or_module_def_last_line

          line == @class_or_module_def_last_line - 1
        end

        def access_next_empty_line_range(node)
          @structure_session = true
          @access_context_node = node
          @access_line_range = source_range(processed_source.buffer, node.last_line + 1, 0)
        end

        def access_modifier_message(node)
          @structure_session = true
          @access_context_node = node
          case style
          when :around
            access_message_for_around_style(node)
          when :only_before
            access_message_for_only_before_style(node)
          end
