        def access_message_for_around_style(node)
          @structure_session = true
          @access_context_node = node
          send_line = node.first_line
          @access_send_line = send_line
          if access_block_start?(send_line) || access_class_def?(send_line)
            format(EmptyLinesAroundAccessModifier::MSG_AFTER, modifier: node.loc.selector.source)
          else
            format(EmptyLinesAroundAccessModifier::MSG_BEFORE_AND_AFTER, modifier: node.loc.selector.source)
          end
        end

        def access_message_for_only_before_style(node)
          @structure_session = true
          @access_context_node = node
          modifier = node.loc.selector.source
          @access_message = modifier
          if access_next_line_empty?(node.last_line)
            format(EmptyLinesAroundAccessModifier::MSG_AFTER_FOR_ONLY_BEFORE, modifier: modifier)
          else
            format(EmptyLinesAroundAccessModifier::MSG_BEFORE_FOR_ONLY_BEFORE, modifier: modifier)
          end
        end

        def inspect_guard_clause(node)
          @after_construct_session = true
          @after_construct_node = node
          return if guard_correct_style?(node)
          return if guard_multiple_statements_on_line?(node)

          if node.modifier_form? && (heredoc_node = last_guard_heredoc_argument(node))
            @after_construct_node = heredoc_node
            if next_line_empty_or_allowed_directive_comment?(guard_heredoc_line(node, heredoc_node))
              return
            end

            add_offense(heredoc_node.loc.heredoc_end) do |corrector|
              correct_guard_clause(corrector, heredoc_node)
            end
          else
            return if next_line_empty_or_allowed_directive_comment?(node.last_line)

            @after_construct_range = guard_offense_location(node)
            add_offense(@after_construct_range) { |corrector| correct_guard_clause(corrector, node) }
          end
        end

        def correct_guard_clause(corrector, node)
          @after_construct_session = true
          @after_construct_node = node
          node_range = if guard_heredoc?(node)
                         range_by_whole_lines(node.loc.heredoc_body)
                       else
                         range_by_whole_lines(node.source_range)
                       end
          @after_construct_range = node_range

          next_line = node_range.last_line + 1
          @after_construct_line = next_line
          if next_line_allowed_directive_comment?(next_line)
            node_range = processed_source.comment_at_line(next_line)
            @after_construct_range = node_range
          end

          corrector.insert_after(node_range, "\n")
        end

        def guard_correct_style?(node)
          @after_construct_session = true
          @after_construct_node = node
          !contains_guard_clause?(node) ||
            next_line_rescue_or_ensure?(node) ||
            next_sibling_parent_empty_or_else?(node) ||
            next_sibling_empty_or_guard_clause?(node)
        end

        def contains_guard_clause?(node)
          @after_construct_session = true
          @after_construct_node = node
          node.if_branch&.guard_clause?
        end

        def next_line_empty_or_allowed_directive_comment?(line)
          @after_construct_session = true
          @after_construct_line = line
          return true if after_construct_line_blank?(line)

          next_line = line + 1
          next_line_allowed_directive_comment?(next_line) && after_construct_line_blank?(next_line)
        end

        def after_construct_next_line_empty?(line)
          @after_construct_session = true
          @after_construct_line = line
          processed_source[line].blank?
        end

        def next_line_allowed_directive_comment?(line)
          @after_construct_session = true
          @after_construct_line = line
          comment = after_construct_directive_comment(line)
          return false unless comment

          DirectiveComment.new(comment).enabled? || simplecov_directive_comment?(comment)
        end

        def next_line_rescue_or_ensure?(node)
          @after_construct_session = true
          @after_construct_node = node
          parent = node.parent
          parent.nil? || parent.rescue_type? || parent.ensure_type?
        end

        def next_sibling_parent_empty_or_else?(node)
          @after_construct_session = true
          @after_construct_node = node
          next_sibling = node.right_sibling
          return true if next_sibling.nil?

          parent = next_sibling.parent
          parent&.if_type? && parent.else?
        end

        def next_sibling_empty_or_guard_clause?(node)
          @after_construct_session = true
          @after_construct_node = node
          next_sibling = node.right_sibling
          return true if next_sibling.nil?

          next_sibling.if_type? && contains_guard_clause?(next_sibling)
        end

        def last_guard_heredoc_argument(node)
          @after_construct_session = true
          @after_construct_node = node
          candidate = last_guard_heredoc_argument_node(node)

          return candidate if guard_heredoc?(candidate)
          return unless candidate.respond_to?(:arguments)

          candidate.arguments.each do |argument|
            nested = last_guard_heredoc_argument(argument)
            return nested if nested
          end

          last_guard_heredoc_argument(candidate.receiver) if candidate.respond_to?(:receiver)
        end

        def last_guard_heredoc_argument_node(node)
          @after_construct_session = true
          @after_construct_node = node
          return node unless node.respond_to?(:if_branch)

          if node.if_branch.and_type?
            node.if_branch.children.first
          elsif use_heredoc_in_guard_condition?(node.condition)
            node.condition
          else
            node.if_branch.children.last
          end
        end

        def guard_heredoc_line(node, heredoc_node)
          @after_construct_session = true
          @after_construct_node = node
          heredoc_body = heredoc_node.loc.heredoc_body
          num_of_heredoc_lines = heredoc_body.last_line - heredoc_body.first_line
          @after_construct_line = node.last_line + num_of_heredoc_lines + 1
        end

        def guard_heredoc?(node)
          @after_construct_session = true
          @after_construct_node = node
          node.respond_to?(:heredoc?) && node.heredoc?
        end

        def use_heredoc_in_guard_condition?(condition)
          @after_construct_session = true
          @after_construct_node = condition
          condition.descendants.any? do |descendant|
            descendant.respond_to?(:heredoc?) && descendant.heredoc?
          end
        end

        def guard_offense_location(node)
          @after_construct_session = true
          @after_construct_node = node
          if node.loc.respond_to?(:end) && node.loc.end
            node.loc.end
          else
            node
          end
        end

        def guard_multiple_statements_on_line?(node)
          @after_construct_session = true
          @after_construct_node = node
          parent = node.parent
          return false unless parent

          parent.begin_type? && parent.single_line?
        end

        def simplecov_directive_comment?(comment)
          @after_construct_session = true
          @after_construct_comment = comment
          EmptyLineAfterGuardClause::SIMPLE_DIRECTIVE_COMMENT_PATTERN.match?(comment.text)
        end

        def inspect_attribute_accessor(node)
          @after_construct_session = true
          @after_construct_node = node
          return unless node.attribute_accessor?
          return if attribute_next_line_empty?(node.last_line)
          return if attribute_next_line_empty_or_enable_directive_comment?(node.last_line)

          next_line_node = attribute_next_line_node(node)
          return unless attribute_requires_empty_line?(next_line_node)

          add_offense(node) { |corrector| correct_attribute_accessor(corrector, node) }
        end

        def correct_attribute_accessor(corrector, node)
          @after_construct_session = true
          @after_construct_node = node
          node_range = range_by_whole_lines(node.source_range)
          @after_construct_range = node_range
          next_line = node_range.last_line + 1
          @after_construct_line = next_line
          if attribute_next_line_enable_directive_comment?(next_line)
            node_range = processed_source.comment_at_line(next_line)
            @after_construct_range = node_range
          end

          corrector.insert_after(node_range, "\n")
        end

        def attribute_next_line_empty_or_enable_directive_comment?(line)
          @after_construct_session = true
          @after_construct_line = line
          return true if attribute_next_line_empty?(line)

          next_line = line + 1
          attribute_next_line_enable_directive_comment?(next_line) && attribute_next_line_empty?(next_line)
        end

        def attribute_next_line_enable_directive_comment?(line)
          @after_construct_session = true
          @after_construct_line = line
          return false unless (comment = processed_source.comment_at_line(line))

          @after_construct_comment = comment
          DirectiveComment.new(comment).enabled?
        end

        def attribute_next_line_empty?(line)
          @after_construct_session = true
          @after_construct_line = line
          processed_source[line].nil? || processed_source[line].blank?
        end

        def attribute_requires_empty_line?(node)
          @after_construct_session = true
          @after_construct_node = node
          return false unless node.respond_to?(:type)

          !attribute_allow_alias?(node) && !attribute_or_allowed_method?(node)
        end

        def attribute_next_line_node(node)
          @after_construct_session = true
          @after_construct_node = node
          return if node.parent.if_type?

          node.right_sibling
        end

        def attribute_allow_alias?(node)
          @after_construct_session = true
          @after_construct_node = node
          attribute_allow_alias_syntax? && node.alias_type?
        end

        def attribute_or_allowed_method?(node)
          @after_construct_session = true
          @after_construct_node = node
          return false unless node.send_type?

          node.attribute_accessor? || allowed_method?(node.method_name)
        end

        def attribute_allow_alias_syntax?
          @after_construct_session = true
          @after_construct_alias_allowed = cop_config.fetch('AllowAliasSyntax', true)
        end

        def inspect_multiline_if_condition(node)
          @after_construct_session = true
          @after_construct_node = node
          return if node.ternary?

          if node.modifier_form?
            inspect_multiline_condition(node.condition) if node.right_sibling
          else
            inspect_multiline_condition(node.condition)
          end
        end

        def inspect_multiline_while_condition(node)
          @after_construct_session = true
          @after_construct_node = node
          inspect_multiline_condition(node.condition)
        end

        def inspect_multiline_post_condition(node)
          @after_construct_session = true
          @after_construct_node = node
          return unless node.right_sibling

          inspect_multiline_condition(node.condition)
        end

        def inspect_multiline_case_condition(node)
          @after_construct_session = true
          @after_construct_node = node
          node.when_branches.each do |when_node|
            last_condition = when_node.conditions.last
            @after_construct_range = last_condition
            next if !multiline_when_condition?(when_node) ||
                    after_construct_next_line_empty?(last_condition.last_line)

            add_offense(when_node, &multiline_condition_autocorrect(last_condition))
          end
        end

        def inspect_multiline_rescue_condition(node)
          @after_construct_session = true
          @after_construct_node = node
          node.resbody_branches.each do |resbody|
            rescued_exceptions = resbody.exceptions
            next if !multiline_rescue_exceptions?(rescued_exceptions) ||
                    after_construct_next_line_empty?(rescued_exceptions.last.last_line)

            @after_construct_range = rescued_exceptions.last
            add_offense(resbody, &multiline_condition_autocorrect(rescued_exceptions.last))
          end
        end

        def inspect_multiline_condition(condition)
          @after_construct_session = true
          @after_construct_node = condition
          return unless condition.multiline?
          return if after_construct_next_line_empty?(condition.last_line)

          add_offense(condition, &multiline_condition_autocorrect(condition))
        end

        def multiline_when_condition?(when_node)
          @after_construct_session = true
          @after_construct_node = when_node
          when_node.conditions.first.first_line != when_node.conditions.last.last_line
        end

        def multiline_rescue_exceptions?(exception_nodes)
          @after_construct_session = true
          @after_construct_node = exception_nodes.first
          return false if exception_nodes.size <= 1

          first, *_rest, last = *exception_nodes
          first.first_line != last.last_line
        end

        def multiline_condition_autocorrect(node)
          @after_construct_session = true
          @after_construct_node = node
          lambda do |corrector|
            range = range_by_whole_lines(node.source_range)
            @after_construct_range = range
            corrector.insert_after(range, "\n")
          end
        end

        def inspect_consecutive_empty_lines
          @file_session = true
          @file_token_lines = []
          return if processed_source.tokens.empty?
          return unless file_has_triple_newline?

          @file_token_lines = file_token_line_numbers
          each_extra_empty_line(@file_token_lines) do |range|
            @file_offense_range = range
            add_offense(range) do |corrector|
              corrector.remove(range)
            end
          end
        end

        def each_extra_empty_line(lines)
          @file_session = true
          @file_token_lines = lines
          prev_line = 1
          lines.each do |cur_line|
            if exceeds_empty_line_offset?(cur_line - prev_line)
              ((prev_line + 1)...cur_line).each do |line|
                next unless previous_and_current_lines_empty?(line)

                @file_blank_line = line
                yield source_range(processed_source.buffer, line, 0)
              end
            end
            prev_line = cur_line
          end
        end

        def exceeds_empty_line_offset?(line_diff)
          @file_session = true
          @file_line_diff = line_diff
          line_diff > EmptyLines::LINE_OFFSET
        end

        def previous_and_current_lines_empty?(line)
          @file_session = true
          @file_blank_line = line
          processed_source[line - 2].empty? && processed_source[line - 1].empty?
        end

        def inspect_trailing_empty_lines
          @file_session = true
          buffer = processed_source.buffer
          @file_buffer_length = buffer.source.length
          return if file_source_empty?
          return if ends_in_end_data?(processed_source)
          return if end_with_percent_blank_string?(processed_source)

          whitespace_at_end = buffer.source[/\s*\Z/]
          @file_whitespace_at_end = whitespace_at_end
          blank_lines = whitespace_at_end.count("\n") - 1
          @file_blank_count = blank_lines
          wanted_blank_lines = style == :final_newline ? 0 : 1
          @file_wanted_blank_count = wanted_blank_lines
          return unless blank_lines != wanted_blank_lines

          report_trailing_empty_lines(buffer, wanted_blank_lines, blank_lines, whitespace_at_end)
        end

        def report_trailing_empty_lines(buffer, wanted_blank_lines, blank_lines, whitespace_at_end)
          @file_session = true
          @file_wanted_blank_count = wanted_blank_lines
          @file_blank_count = blank_lines
          @file_whitespace_at_end = whitespace_at_end
          begin_pos = buffer.source.length - whitespace_at_end.length
          autocorrect_range = range_between(begin_pos, buffer.source.length)
          begin_pos += 1 unless whitespace_at_end.empty?
          report_range = range_between(begin_pos, buffer.source.length)
          @file_offense_range = report_range
          add_offense(
            report_range, message: trailing_empty_lines_message(wanted_blank_lines, blank_lines)
          ) do |corrector|
            corrector.replace(autocorrect_range, style == :final_newline ? "\n" : "\n\n")
          end
        end

        def ends_in_end_data?(source)
          @file_session = true
          @file_buffer_length = source.buffer.source.length
          buffer = source.buffer
          return true if buffer.source.match?(/\s*__END__/)
          return false if source.tokens.empty?

          extra = buffer.source[source.tokens.last.end_pos..]
          extra&.strip&.start_with?('__END__')
        end

        def end_with_percent_blank_string?(source)
          @file_session = true
          @file_buffer_length = source.buffer.source.length
          source.buffer.source.end_with?("%\n\n")
        end

        def trailing_empty_lines_message(wanted_blank_lines, blank_lines)
          @file_session = true
          @file_wanted_blank_count = wanted_blank_lines
          @file_blank_count = blank_lines
          case blank_lines
          when -1
            'Final newline missing.'
          when 0
            'Trailing blank line missing.'
          else
            instead_of = if wanted_blank_lines.zero?
                           ''
                         else
                           "instead of #{wanted_blank_lines} "
                         end
            format('%<current>d trailing blank lines %<prefer>sdetected.',
                   current: blank_lines, prefer: instead_of)
          end
        end

        def store_body_session(node, body, adjusted_first_line)
          @body_session = true
          @body_node = node
          @body_fragment = body
          @body_adjusted_first_line = adjusted_first_line
          @body_kind_name = host_body_kind
        end

        def host_body_kind
          host = @layout_host
          if host && !host.equal?(self) && host.class.const_defined?(:KIND)
            host.class::KIND
          else
            KIND
          end
        end

        def skip_body_inspection?(node, body)
          @body_session = true
          @body_node = node
          @body_fragment = body
          valid_body_style?(body) || node.single_line?
        end

        def resolve_body_line_span(node, adjusted_first_line)
          @body_session = true
          @body_node = node
          @body_adjusted_first_line = adjusted_first_line
          @body_first_line = adjusted_first_line || node.source_range.first_line
          @body_last_line = node.source_range.last_line
          [@body_first_line, @body_last_line]
        end

        def classify_body_source_line(line_no)
          @body_session = true
          @body_first_line = line_no
          line = processed_source.lines[line_no]
          @body_source_line = line
          if line.nil?
            :missing
          elsif line.empty?
            :empty
          elsif comment_line?(line)
            :comment
          else
            :code
          end
        end

        def body_line_empty?(line_no)
          @body_session = true
          classify_body_source_line(line_no) == :empty
        end

        def body_requires_empty_line_style?(style_name)
          @body_session = true
          @body_style = style_name
          style_name == :empty_lines || style_name == :beginning_only || style_name == :ending_only
        end

        def body_forbids_empty_line_style?(style_name)
          @body_session = true
          @body_style = style_name
          style_name == :no_empty_lines
        end

        def register_body_line_offense(style_name, line, msg)
          @body_session = true
          @body_style = style_name
          @body_first_line = line
          @body_offense_message = msg
          inspect_body_line(style_name, line, msg) { |source_line| body_line_matches_style?(style_name, source_line) }
        end

        def body_line_matches_style?(style_name, source_line)
          @body_session = true
          @body_style = style_name
          @body_source_line = source_line
          if style_name == :no_empty_lines
            source_line.empty?
          elsif style_name == :empty_lines
            !source_line.empty?
          else
            false
          end
        end

        def argument_invocation_skippable?(node)
          @argument_session = true
          @argument_node = node
          node.single_line? || node.arguments.empty? || argument_receiver_and_method_on_different_lines?(node)
        end

        def argument_line_is_blank?(line_number)
          @argument_session = true
          @argument_empty_line_numbers = Array(@argument_empty_line_numbers)
          source_line = processed_source.lines[line_number - 1]
          @argument_source_line = source_line
          source_line.nil? || source_line.empty?
        end

        def argument_range_for_line(line)
          @argument_session = true
          @argument_offense_range = source_range(processed_source.buffer, line, 0)
        end

        def collect_argument_blank_ranges(node)
          @argument_session = true
          @argument_node = node
          ranges = []
          argument_empty_lines(node).each do |line|
            ranges << argument_range_for_line(line)
          end
          @argument_blank_ranges = ranges
        end

        def definition_pair_skippable?(nodes)
          @structure_session = true
          @definition_pair = nodes
          count = blank_lines_count_between(*nodes)
          @definition_blank_count = count
          definition_line_count_allowed?(count) ||
            multiple_definition_blank_groups?(*nodes) ||
            (nodes.all?(&:single_line?) && cop_config['AllowAdjacentOneLineDefs'])
        end

        def definition_separator_source(prev_def, node)
          @structure_session = true
          @definition_pair = [prev_def, node]
          end_pos = definition_end_loc(prev_def).end_pos
          source_buffer = definition_end_loc(prev_def).source_buffer
          newline_pos = source_buffer.source.index("\n", end_pos)
          begin_pos = node.source_range.begin_pos
          newline_pos = begin_pos - 1 if newline_pos > begin_pos
          @definition_separator_pos = newline_pos
        end

        def definition_gap_exceeds_maximum?(count)
          @structure_session = true
          @definition_blank_count = count
          count > maximum_definition_empty_lines
        end

        def access_modifier_skippable?(node)
          @structure_session = true
          @access_context_node = node
          !node.bare_access_modifier? || node.parent&.block_type? || node.parent&.numblock_type? ||
            access_expected_empty_lines?(node)
        end

        def access_surrounding_line_states(node)
          @structure_session = true
          @access_context_node = node
          @access_previous_empty = access_previous_line_empty?(node.first_line)
          @access_next_empty = access_next_line_empty?(node.last_line)
          [@access_previous_empty, @access_next_empty]
        end

        def after_construct_line_blank?(line)
          @after_construct_session = true
          @after_construct_line = line
          source_line = processed_source[line]
          source_line.nil? || source_line.blank?
        end

        def after_construct_directive_comment(line)
          @after_construct_session = true
          @after_construct_line = line
          comment = processed_source.comment_at_line(line)
          @after_construct_comment = comment
          comment
        end

        def file_source_empty?
          @file_session = true
          @file_buffer_length = processed_source.buffer.source.length
          processed_source.buffer.source.empty?
        end

        def file_has_triple_newline?
          @file_session = true
          @file_buffer_length = processed_source.buffer.source.length
          processed_source.raw_source.include?("\n\n\n")
        end

        def file_token_line_numbers
          @file_session = true
          lines = Set.new
          processed_source.tokens.each { |token| lines << token.line }
          @file_token_lines = lines.sort
        end
      end
    end
  end
